// Фикстура (a): 64 такта = 4 такта × 16 с одним sweep на фильтре.
//
// Трек технически безупречен: ровный ритм, много атак, всё в ладу.
// Материал — 4 такта, повторённые 16 раз, и ЕДИНСТВЕННОЕ, что меняется, —
// медленный sweep на фильтре. На слух трек «дышит», но структурно это один
// цикл: ни секций, ни смены гармонии, ни развития.
//
// Скор v2 должен быть низким именно за это: размах энергии ноль,
// гармония не меняется, новизна нулевая.
//
// Настоящий код Strudel: `loop(16, …)` повторяет 4-тактовый материал.

setCpm(124/4)
const key = "c:minor"

const CYCLE = [
  s("bd*4"),
  s("hh*16"),
  s("~ cp ~ cp"),
  n("0 0 3 5").scale(key).s("sawtooth"),
  stack(
    n("0 2 4").scale(key),
    n("3 5 7").scale(key),
  ).s("sawtooth"),
];

$KICK: loop(16, s("bd*4")).gain(0.9)._scope()
$HATS: loop(16, s("hh*16")).gain(0.35)._scope()
$SNARE: loop(16, s("~ cp ~ cp")).gain(0.6)._scope()
$BASS: loop(16, n("0 0 3 5").scale(key).s("sawtooth")).lpf(sine.slow(64).range(300, 4000)).gain(0.6)._pianoroll()
$PAD: loop(16, stack(
  n("0 2 4").scale(key),
  n("3 5 7").scale(key),
).s("sawtooth")).gain(0.25)._pianoroll()
